import{f as a,o as s,c as e,a2 as p}from"./chunks/framework.Cd9rfTEn.js";const m=JSON.parse('{"title":"Prompt — PPT catálogo exhaustivo de funciones (desde enumeración por aplicativo)","description":"","frontmatter":{},"headers":[],"relativePath":"presentacion-stakeholders/enumeracion-ppt-catálogo-funciones-PROMPT-CLAUDE.md","filePath":"presentacion-stakeholders/enumeracion-ppt-catálogo-funciones-PROMPT-CLAUDE.md","lastUpdated":null}'),o={name:"presentacion-stakeholders/enumeracion-ppt-catálogo-funciones-PROMPT-CLAUDE.md"};function l(i,n,r,t,c,d){return s(),e("div",null,[...n[0]||(n[0]=[p(`<h1 id="prompt-—-ppt-catalogo-exhaustivo-de-funciones-desde-enumeracion-por-aplicativo" tabindex="-1">Prompt — PPT catálogo exhaustivo de funciones (desde enumeración por aplicativo) <a class="header-anchor" href="#prompt-—-ppt-catalogo-exhaustivo-de-funciones-desde-enumeracion-por-aplicativo" aria-label="Permalink to &quot;Prompt — PPT catálogo exhaustivo de funciones (desde enumeración por aplicativo)&quot;">​</a></h1><p><strong>Adjunto obligatorio:</strong> <a href="./enumeracion-funciones-por-aplicativo"><code>enumeracion-funciones-por-aplicativo.md</code></a></p><p><strong>Opcional (catálogo 1:1 con menú T03, 558 ítems):</strong> carpeta <code>docs/entregables-analisis-diseno/22-mapa-navegacion/</code> (<code>22-01-admin-C01-C10.md</code>, <code>22-02-admin-C11-C18.md</code>) + tablas <code>SM-PWS-*</code> en T03 §10.8.</p><p><strong>Alcance del MD adjunto (nov 2026):</strong> gestión web <strong>329</strong> líneas funcionales vs <strong>402</strong> ítems de menú oficiales; faltan sobre todo C05, C11 y C18. El socio tiene <strong>48</strong> líneas vs <strong>49</strong> ítems <code>SM-PWS</code>. Si el usuario pide “cada pantalla del menú”, priorizar mapa 22 + T03; si pide “cada línea del MD adjunto”, seguir el MD al pie de la letra.</p><p><strong>Salida deseada:</strong> PowerPoint (o HTML→PNG por slide) <strong>1920×1080</strong>, español Argentina.</p><hr><h2 id="a-bloque-para-copiar-y-pegar-en-claude-primero" tabindex="-1">A. Bloque para copiar y pegar en Claude (primero) <a class="header-anchor" href="#a-bloque-para-copiar-y-pegar-en-claude-primero" aria-label="Permalink to &quot;A. Bloque para copiar y pegar en Claude (primero)&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sos diseñador de presentaciones para cooperativas de servicios públicos de Argentina.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>OBJETIVO: armar una PPT que muestre TODAS Y CADA UNA de las funciones listadas en el documento adjunto &quot;enumeracion-funciones-por-aplicativo.md&quot;, sin omitir ninguna línea numerada.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>NO es un deck de marketing &quot;lo nuevo vs ProCoop&quot;. Es un CATÁLOGO VISUAL: inventario completo por aplicativo y por módulo.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== AUDIENCIA ===</span></span>
<span class="line"><span>- Gerencia: entiende alcance del producto (&quot;qué puede hacer el sistema&quot;).</span></span>
<span class="line"><span>- Jefes de área: reconocen su menú y sus pantallas.</span></span>
<span class="line"><span>- Técnica: puede usar pie diminuto con referencia al doc; no hace falta detalle de implementación en el cuerpo.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== PROHIBIDO (texto grande visible) ===</span></span>
<span class="line"><span>Códigos SM-ADM-001, M01, T04, PC-077, RF-, O11, olas, &quot;equivalente en Mxx&quot;.</span></span>
<span class="line"><span>Palabras vacías: revolucionario, disruptivo, el mejor, sin ProCoop.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== PERMITIDO ===</span></span>
<span class="line"><span>Nombres de aplicativo: &quot;Sistema de gestión web&quot;, &quot;App del socio&quot;, &quot;ProCoop.exe&quot;, &quot;CoopOnline&quot;, etc.</span></span>
<span class="line"><span>Nombres de módulo tal como en el MD: &quot;C05 Facturación&quot;, &quot;Módulo: Cuentas y servicios&quot;, pestañas ProCoop.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== REGLA DE COMPLETITUD (CRÍTICA) ===</span></span>
<span class="line"><span>1. Recorré el MD adjunto en orden: Parte 1 (CoopApps) → Parte 2 (legacy) → ignorar Parte 3 salvo slide de cierre opcional.</span></span>
<span class="line"><span>2. Cada función del MD (cada línea numerada, ej. &quot;12. Titulares: …&quot;) debe aparecer EXACTAMENTE UNA VEZ en la presentación, con el mismo texto (puedes acortar solo si supera 120 caracteres y entonces usar &quot;…&quot; marcando que es el mismo ítem).</span></span>
<span class="line"><span>3. No fusionar dos ítems del MD en un solo bullet.</span></span>
<span class="line"><span>4. No inventar funciones que no estén en el MD (salvo títulos de sección).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== ESTRATEGIA DE SLIDES (para no hacer 400 diapositivas sueltas) ===</span></span>
<span class="line"><span>Usá este patrón híbrido (obligatorio):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SLIDE-TIPO 1 — Separador de aplicativo</span></span>
<span class="line"><span>- Título: nombre del aplicativo (ej. &quot;1. Sistema de gestión web&quot;)</span></span>
<span class="line"><span>- Subtítulo: cantidad total del MD para esa app</span></span>
<span class="line"><span>- Mini índice: lista de módulos de esa app (solo nombres de módulo, sin funciones)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SLIDE-TIPO 2 — Tabla por módulo</span></span>
<span class="line"><span>- Título: &quot;Módulo: [nombre]&quot; + aplicativo entre paréntesis si hace falta</span></span>
<span class="line"><span>- Subtítulo: &quot;N funciones&quot; (copiar del MD)</span></span>
<span class="line"><span>- Tabla de UNA columna o dos columnas:</span></span>
<span class="line"><span>  - Col A: número global o local + texto literal de la función (del MD)</span></span>
<span class="line"><span>  - Col B (opcional, 9px gris): una frase &quot;Para qué sirve&quot; si yo la pido en un segundo paso; por defecto dejá vacío</span></span>
<span class="line"><span>- Máximo 12 filas por slide; si el módulo tiene más, continuá en &quot;Módulo X — parte B, C…&quot; hasta vaciar TODAS las funciones.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SLIDE-TIPO 3 — Legacy ProCoop</span></span>
<span class="line"><span>- Misma lógica: por módulo (pestaña / subárea), tablas con cada ítem numerado del MD.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SLIDE-TIPO 0 — Portada</span></span>
<span class="line"><span>- Título: &quot;Catálogo de funciones — ProCoop y CoopApps&quot;</span></span>
<span class="line"><span>- Subtítulo: &quot;Una función por fila · orden por aplicativo y módulo&quot;</span></span>
<span class="line"><span>- Fecha y nota: &quot;Fuente: enumeracion-funciones-por-aplicativo.md&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SLIDE-TIPO Z — Cierre (opcional)</span></span>
<span class="line"><span>- Tabla resumen: aplicativo | # módulos | # funciones (sumar desde el MD)</span></span>
<span class="line"><span>- Una línea de honestidad: &quot;Gestión web: listado desglosado 329 líneas; catálogo de menú oficial 402 ítems T03&quot; (solo si consta en el MD)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== PALETA ===</span></span>
<span class="line"><span>Fondo claro #F9FAFB; títulos #1F2937; acento CoopApps #2E7D32; legacy ProCoop #6B7280 en subtítulos de Parte 2.</span></span>
<span class="line"><span>Tipografía sans legible; cuerpo mínimo 14px en tablas; títulos 28–32px.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== FORMATO DE ENTREGA ===</span></span>
<span class="line"><span>Primero: outline numerado (lista de todos los slides con código PPT-CAT-001, PPT-CAT-002…) indicando qué funciones (# del MD) incluye cada slide.</span></span>
<span class="line"><span>Después: cuando yo escriba &quot;Generá PPT-CAT-001&quot; (o &quot;todos los slides en un archivo HTML por slide&quot;), producí ese slide en HTML+SVG 1920×1080 listo para exportar a PNG/PPT.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== VERIFICACIÓN ===</span></span>
<span class="line"><span>Al final del outline, tabla de control:</span></span>
<span class="line"><span>| Aplicativo | Funciones en MD | Funciones asignadas a slides | ¿Coincide? |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Si no coincide, corregí antes de diseñar.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Confirmá que leíste el adjunto y esperá mi &quot;Generá outline&quot; o &quot;Generá todos&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br><span class="line-number">61</span><br><span class="line-number">62</span><br><span class="line-number">63</span><br><span class="line-number">64</span><br><span class="line-number">65</span><br><span class="line-number">66</span><br><span class="line-number">67</span><br><span class="line-number">68</span><br></div></div><hr><h2 id="b-comandos-que-le-podes-decir-despues" tabindex="-1">B. Comandos que le podés decir después <a class="header-anchor" href="#b-comandos-que-le-podes-decir-despues" aria-label="Permalink to &quot;B. Comandos que le podés decir después&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comando</th><th>Qué hace</th></tr></thead><tbody><tr><td><code>Generá outline</code></td><td>Índice PPT-CAT-* + tabla de control de completitud</td></tr><tr><td><code>Generá PPT-CAT-001</code></td><td>Solo portada</td></tr><tr><td><code>Generá slides de la app 1 (gestión web) completos</code></td><td>Todos los módulos C01–C18 del MD, sin saltear</td></tr><tr><td><code>Generá solo Parte 2 ProCoop</code></td><td>Escritorio + CoopOnline + P-Móvil + Agente + Integra</td></tr><tr><td><code>Exportá en un solo PPTX</code></td><td>Si el modelo soporta archivo; si no, HTML por slide + instrucción de importar</td></tr></tbody></table><hr><h2 id="c-variante-si-queres-402-558-items-de-menu-no-solo-el-md" tabindex="-1">C. Variante si querés 402 + 558 ítems de menú (no solo el MD) <a class="header-anchor" href="#c-variante-si-queres-402-558-items-de-menu-no-solo-el-md" aria-label="Permalink to &quot;C. Variante si querés 402 + 558 ítems de menú (no solo el MD)&quot;">​</a></h2><p>Pegá además este párrafo <strong>después</strong> del bloque §A:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AMPLIACIÓN: además del MD, usá los archivos 22-01-admin-C01-C10.md y 22-02-admin-C11-C18.md:</span></span>
<span class="line"><span>cada fila SM-ADM con columna &quot;Ítem&quot; = una fila obligatoria en la PPT (402 filas en gestión).</span></span>
<span class="line"><span>Mismas reglas de tablas por módulo (cluster C01–C18), máximo 12 filas por slide.</span></span>
<span class="line"><span>En socio/empleado/campo/landing: tabla T03 §10.8 (SM-PWS, SM-EMP, etc.) hasta total 558.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><hr><h2 id="d-relacion-con-otros-decks" tabindex="-1">D. Relación con otros decks <a class="header-anchor" href="#d-relacion-con-otros-decks" aria-label="Permalink to &quot;D. Relación con otros decks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Deck</th><th>Uso</th></tr></thead><tbody><tr><td>Este (PPT-CAT)</td><td>Inventario total — auditoría, capacitación, alcance contractual</td></tr><tr><td>IMG-F + megaspec</td><td>Comparativo ProCoop vs CoopApps por función</td></tr><tr><td>IMG-N</td><td>Marketing &quot;lo nuevo&quot;</td></tr></tbody></table>`,18)])])}const b=a(o,[["render",l]]);export{m as __pageData,b as default};
